export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function metric(value,unit='',digits=2){return typeof value==='number'&&Number.isFinite(value)?value.toLocaleString('en-IN',{maximumFractionDigits:digits})+(unit?' '+unit:''):'Not measured';}
export function measuredMetric(stats,key,unit){return stats?.measurement_available===true?metric(stats[key],unit):'Not measured';}
const esc=escapeHTML;
const tile=(title,value,copy)=>`<article class="impact-tile"><span>${esc(title)}</span><strong>${esc(value)}</strong><p>${esc(copy)}</p></article>`;
export function impactMarkup(overall,personal){
 const live=personal?.live,life=personal?.lifetime,all=overall.completed,funds=personal?.contributions,heat=overall.heat;
 const person=personal?`<p class="muted">Your account journey began ${esc(new Date(personal.since).toLocaleDateString('en-IN'))}. Driver figures show impact enabled by your rides; the platform counts each booking once.</p><div class="impact-grid">${tile('LIVE · THIS JOURNEY',measuredMetric(live,'co2_kg','kg CO₂'),'Estimated avoided tailpipe emissions on eligible GPS-tracked shared segments. In-progress totals are provisional.')}${tile('YOUR COMPLETED JOURNEYS',measuredMetric(life,'co2_kg','kg CO₂'),'Accumulated estimate from completed eligible journeys since joining. Missing data is not counted as a saving.')}${tile('TREE FUND · AS A RIDER',metric(funds?.rider_inr,'INR'),'Recorded Green Fund allocations attributed to your completed, paid journeys.')}${tile('TREE FUND · AS AN OWNER',metric(funds?.owner_inr,'INR'),'Recorded allocations attributed to journeys you operated. These are not direct donations or a percentage of fare.')}</div>`:'<div class="panel"><h2>Your journey, your contribution.</h2><p>Sign in to see live estimates, your accumulated impact and recorded tree-fund contributions.</p><button class="button dark" data-view="account">Sign in</button></div>';
 return `${person}<h2 class="impact-subtitle">Together, across Planto-Ride.</h2><div class="impact-grid">${tile('COMPLETED SHARED JOURNEYS',measuredMetric(all,'co2_kg','kg CO₂'),'Estimated avoided tailpipe emissions. Rider and owner credits are not added together.')}${tile('VEHICLE-HOURS AVOIDED',measuredMetric(all,'vehicle_hours','hours'),'Modelled solo-car time removed from the road. This is not measured passenger time saved or a city congestion reduction.')}${tile('RECORDED TREE ALLOCATIONS',metric(overall.trees?.allocated_inr,'INR'),`${metric(overall.trees?.trees_recorded,'trees',0)} recorded in evidence-backed allocation entries. Zero means no records yet.`)}${tile('LOCAL HEAT STUDY',metric(heat?.reduction_c,'°C'),heat?.reduction_c==null?'No temperature study has been recorded. Carbon savings cannot be converted directly into a city temperature reduction.':`Reported change at ${heat.scope||'the recorded study site'}. Site-level association; not a citywide temperature claim.`)}</div>${heat?.reduction_c!=null?`<p class="muted">Study scope: ${esc(heat.scope)} · Evidence: ${esc(heat.reference)} · Measurement: ${esc(heat.measured_at||'See study record')}</p>`:''}<details class="impact-method"><summary>How these figures are calculated</summary><p>Carbon estimates apply only when a shared-ride owner confirms the journey was already planned and a rider says their party would otherwise use one solo car. One party counts as one avoided car, regardless of seat count.</p><p>Accepted foreground GPS segments × 0.249 kg CO₂/km, using an illustrative US petrol-car proxy. This is not a Pune fleet measurement, a lifecycle footprint or a carbon credit. Untracked segments, private cars, bikes and unknown alternatives receive no savings claim.</p><p>Vehicle-hours use the duration of those accepted segments. The 50% annual net profit after tax pledge is separate from fares; only recorded allocations appear as tree funding. A local temperature result needs a dated study with comparison-site readings, not an automatic carbon-to-degrees calculation.</p><a href="methodology.html">Read the full methodology and evidence requirements ↗</a></details><p class="muted">Updated ${esc(new Date().toLocaleTimeString())}. Refreshes while this tab is open; figures depend on the connected booking service.</p>`;
}
export function createCompanion({api,getUser,getView,openSOS,toast}){
 const $=s=>document.querySelector(s),dialog=$('#captain-dialog');
 let bookingId=null,lastRender='',loading=false,sending=false,request=null,session=null,epoch=0,chatRequest=0,pendingCheckin=null;
 async function loadImpact(){
  const target=$('#impact-content'),user=getUser(),version=epoch;
  try{const [overall,personal]=await Promise.all([api.request('/v1/impact/overall'),user?api.request('/v1/impact/me'):Promise.resolve(null)]);if(version!==epoch||getUser()?.id!==user?.id)return;const expanded=target.querySelector('details')?.open;target.innerHTML=impactMarkup(overall,personal);if(expanded)target.querySelector('details').open=true;}
  catch(e){if(version===epoch)target.innerHTML=`<div class="empty-state"><h2>Impact data is unavailable.</h2><p>${esc(e.message)}</p><p>Impact figures will appear when the service is available.</p></div>`;}
 }
 function renderChat(data){
  $('#captain-name').textContent=data.captain.name;
  $('#captain-identity').textContent='Automated ride assistant · '+data.captain.id;
  $('#captain-state').textContent=data.concern_reported?'A concern was recorded for manual review. This is not a monitored emergency service.':data.checkin?.status==='awaiting'?'Captain is waiting for your check-in. No reply is not proof that you are safe or unsafe.':'Check-ins reflect your replies; they do not verify that a ride is safe.';
  pendingCheckin=data.checkin?.status==='awaiting'?data.checkin.id:null;$('#captain-good').disabled=sending||!pendingCheckin;
  $('#captain-good').dataset.checkin=data.checkin?.status==='awaiting'?data.checkin.id:'';
  const content=JSON.stringify(data.messages);
  if(content!==lastRender){lastRender=content;$('#captain-messages').innerHTML=data.messages.map(m=>`<div class="chat-message ${m.role==='rider'?'from-rider':'from-captain'}"><strong>${m.role==='rider'?'You':'Captain'}</strong><p>${esc(m.text)}</p><time>${esc(new Date(m.created*1000).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}))}</time></div>`).join('');$('#captain-messages').scrollTop=$('#captain-messages').scrollHeight;}
 }
 async function loadChat(){if(!bookingId||loading||sending)return;loading=true;const id=bookingId,version=epoch,ticket=++chatRequest;try{const data=await api.request('/v1/bookings/'+encodeURIComponent(id)+'/captain');if(id===bookingId&&version===epoch&&ticket===chatRequest)renderChat(data);}catch(e){if(version===epoch&&ticket===chatRequest)$('#captain-error').textContent=e.message;}finally{if(ticket===chatRequest)loading=false;}}
 async function open(id){if(!getUser()){toast('Sign in to chat with your Captain.');return;}bookingId=id;chatRequest++;loading=false;pendingCheckin=null;$('#captain-good').dataset.checkin='';$('#captain-name').textContent='Your Captain';$('#captain-identity').textContent='Automated ride assistant';$('#captain-state').textContent='Loading your conversation.';lastRender='';request=null;$('#captain-messages').replaceChildren();$('#captain-error').textContent='';$('#captain-text').value='';$('#captain-good').disabled=true;dialog.showModal();await loadChat();}
 async function send(action){if(sending||!bookingId)return;const text=action?({all_good:'All good',need_help:'I need help',unsafe:'I feel unsafe',status:'Trip status'})[action]:$('#captain-text').value.trim();if(!text)return;
  const checkin=['all_good','need_help','unsafe'].includes(action)?$('#captain-good').dataset.checkin:undefined;if(action==='all_good'&&!checkin)return;
  const payload={text,...(action?{action}:{}),...(checkin?{checkin_id:checkin}:{})};const fingerprint=JSON.stringify(payload);if(request?.fingerprint!==fingerprint)request={fingerprint,payload:{...payload,request_id:crypto.randomUUID()}};
  sending=true;chatRequest++;loading=false;$('#captain-error').textContent='';dialog.querySelectorAll('[data-captain-action],#captain-send').forEach(b=>b.disabled=true);const version=epoch,id=bookingId;
  try{const data=await api.request('/v1/bookings/'+encodeURIComponent(id)+'/captain/messages','POST',request.payload);if(version!==epoch||id!==bookingId)return;request=null;$('#captain-text').value='';renderChat(data);await poll();}catch(e){if(version===epoch&&id===bookingId)$('#captain-error').textContent=e.message+' Retry the same message if needed.';}finally{sending=false;dialog.querySelectorAll('[data-captain-action],#captain-send').forEach(b=>b.disabled=false);$('#captain-good').disabled=!pendingCheckin;if(dialog.open)void loadChat();}
 }
 async function poll(){const user=getUser();if(!user||document.hidden)return;const version=epoch;try{const data=await api.request('/v1/captain/checkins');if(version!==epoch||getUser()?.id!==user.id)return;const list=data.checkins.filter(c=>c.status==='awaiting');$('#captain-banner').hidden=!list.length;$('#captain-banner-copy').textContent=list.length?'Your Captain is checking in. How is your ride going?':'';$('#captain-banner-open').dataset.booking=list[0]?.booking_id||'';}catch{if(version===epoch){$('#captain-banner').hidden=false;$('#captain-banner-copy').textContent='Captain connection unavailable. Automated check-ins cannot be delivered right now.';$('#captain-banner-open').dataset.booking='';}}}
 function sessionChanged(){const next=getUser()?.id||null;if(next===session)return;session=next;epoch++;chatRequest++;loading=false;pendingCheckin=null;bookingId=null;lastRender='';request=null;$('#captain-messages').replaceChildren();$('#impact-content').replaceChildren();$('#captain-banner').hidden=true;if(dialog.open)dialog.close();if(next)void poll();if(getView()==='impact')void loadImpact();}
 $('#captain-close').onclick=()=>{dialog.close();bookingId=null;};dialog.addEventListener('close',()=>{bookingId=null;});$('#captain-sos').onclick=()=>{dialog.close();bookingId=null;openSOS();};
 $('#captain-form').onsubmit=e=>{e.preventDefault();void send();};dialog.querySelectorAll('[data-captain-action]').forEach(b=>b.onclick=()=>void send(b.dataset.captainAction));$('#captain-banner-open').onclick=e=>{const id=e.currentTarget.dataset.booking;if(id)void open(id);else toast('Use SOS for urgent help. Captain is currently unavailable.');};$('#refresh-impact').onclick=()=>void loadImpact();
 const timer=setInterval(()=>{if(document.hidden)return;sessionChanged();if(getUser())void poll();if(dialog.open&&!sending)void loadChat();if(getView()==='impact')void loadImpact();},15000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden){void poll();if(dialog.open)void loadChat();}});
 return {open,loadImpact,sessionChanged,destroy(){clearInterval(timer);}};
}
